import * as S from './science.mjs';
export const fmt=(n,d=2)=>Number.isFinite(n)?Number(n.toFixed(d)).toLocaleString('en-GB',{maximumFractionDigits:d}):'—';
const range=(id,label,value,min,max,step=1,unit='')=>({id,label,value,min,max,step,unit});
const select=(id,label,value,options)=>({id,label,value,options});
const question=(prompt,correct,wrong,why)=>({prompt,options:[correct,...wrong],answer:0,why});
const result=(readings,equation,explanation,question,plot)=>({readings,equation,explanation,question,plot});
const step=(label,source,target,tool)=>({label,source,target,tool});
export const units=[
 {id:'electricity',name:'Electricity and electrostatics',intro:'Build a circuit, measure electric force, diagnose protection devices and investigate the energy behind an electricity bill.',categories:['Current and charge','Voltage and resistance','Circuits and power','Coulomb’s law','Electrical safety','Energy consumption'],lessons:[
 ['Charge, current and potential difference','Current is charge flow per second: I = Q/t. Potential difference is energy transferred per coulomb: V = E/Q. Conventional current leaves the positive terminal; electrons in metal drift the other way.','A current of 0.50 A transfers 30 C in one minute. A 6 V supply transfers 6 J per coulomb.'],
 ['Series and parallel circuits','Series components carry the same current and share the supply voltage. Parallel branches have the same voltage; branch currents add. Use V = IR for an ohmic resistor at constant temperature.','At 6 V, 10 Ω and 20 Ω in series give I = 0.20 A. In parallel, the branch currents are 0.60 A and 0.30 A.'],
 ['Force between charges','For ideal point charges, F = k|q₁q₂|/r². Like signs repel and unlike signs attract. Convert μC to C and use centre-to-centre distance in metres. A field is force per positive test charge; field arrows point away from positive charges.','Doubling separation quarters the force; changing one charge’s sign reverses direction without changing magnitude. Fields are an optional extension in the charge investigation.'],
 ['Power and energy','P = VI = I²R = V²/R for a resistor. Electrical energy E = Pt. Bills use kWh, a unit of energy: 1 kWh = 3.6 MJ. A tariff is a price per kWh.','A 2 kW heater used for 3 h consumes 6 kWh. At 0.30 currency units/kWh this costs 1.80.'],
 ['Protection and safe isolation','An overcurrent breaker or fuse protects wiring against excessive current. An RCD compares outgoing and returning current and disconnects when there is sufficient imbalance. Earthing provides a protective path. An RCD does not replace overcurrent protection.','Use the virtual fault board to compare an earth fault with a balanced overload. This isolated diagram is a model, not instructions to work on a real mains socket.']
 ]},
 {id:'waves',name:'Waves and sound',intro:'Make waves, compare sound signals, explore electromagnetic radiation and observe reflection, refraction and diffraction.',categories:['Wave properties','Longitudinal and transverse','Sound and echoes','Doppler effect','Electromagnetic spectrum','Wave behaviour'],lessons:[
 ['Wave speed, frequency and wavelength','A wave transfers energy without a net transport of the medium. v = fλ and T = 1/f. In a transverse wave, oscillations are perpendicular to travel; in a longitudinal wave they are parallel.','A 5 Hz wave with wavelength 2 m travels at 10 m/s. Watch one marked particle rather than following a travelling crest.'],
 ['Pitch, loudness and echoes','Higher frequency means higher pitch. Larger pressure amplitude generally means a louder sound at the same frequency; it does not raise the frequency. Sound needs a medium. Echo distance is half the sound’s round-trip travel.','At 340 m/s, an echo after 0.50 s comes from a surface 85 m away.'],
 ['The Doppler effect','A moving source crowds wavefronts ahead and spreads them behind. For a stationary observer and approaching subsonic source, f′ = fv/(v − vₛ); for recession use v + vₛ.','For a 600 Hz siren moving at 20 m/s through air at 340 m/s, a stationary observer hears about 638 Hz ahead and 567 Hz behind.'],
 ['Electromagnetic radiation','Radio, microwave, infrared, visible, ultraviolet, X-ray and gamma radiation are all transverse electromagnetic waves. All travel at c ≈ 3.00 × 10⁸ m/s in vacuum; frequency rises as wavelength falls.','Microwaves can carry communications; infrared is used in thermal imaging; X-rays form images but require controlled exposure. The spectrum diagram is arranged by band, not a linear wavelength scale.'],
 ['Wave behaviour at boundaries','Reflection changes direction within the original medium. Refraction changes speed and usually direction at a boundary, while frequency stays the same. Diffraction spreads waves at gaps; spreading is more pronounced when the gap is comparable to wavelength.','Water waves entering shallower water usually slow down: unchanged f and smaller v mean a smaller wavelength.']
 ]},
 {id:'optics',name:'Optics and cameras',intro:'Rotate a mirror, trace refracted rays, move lenses and focus a camera on its sensor.',categories:['Reflection and mirrors','Refraction and Snell’s law','Total internal reflection','Converging lenses','Diverging lenses','Cameras and applications'],lessons:[
 ['Reflection, visibility and mirrors','Angles of incidence and reflection are measured from the normal and are equal. A plane mirror forms an upright virtual image the same distance behind as the object is in front. A ray reaches an eye only if its complete path is clear.','Moving a card can block one ray while leaving another clear. A ball can still be visible around the card if another ball → mirror → eye path is unobstructed.'],
 ['Refraction and Snell’s law','n₁ sin i = n₂ sin r. Entering a higher refractive index bends a non-normal ray towards the normal; its speed and wavelength decrease while frequency stays fixed.','From air into glass (n = 1.5) at i = 30°, r = asin(sin30°/1.5) ≈ 19.5°.'],
 ['Total internal reflection','TIR requires travel from a higher to a lower refractive index and incidence above the critical angle. At the critical angle the refracted ray lies along the boundary. sin c = n₂/n₁.','Glass (1.5) to air has c ≈ 41.8°. At 50°, no transmitted ray emerges in this ideal model.'],
 ['Lens equations and signs','Use 1/f = 1/u + 1/v, with u positive for the real object here, f positive for a converging lens and negative for a diverging lens. Positive v indicates a real image; negative v a virtual image. Magnification m = −v/u. The drawing is a thin-lens, paraxial model.','For f = +10 cm and u = 30 cm, v = +15 cm and m = −0.5: real, inverted and half-height. A diverging lens with f = −10 cm and u = 30 cm gives v = −7.5 cm.'],
 ['Cameras and focusing','A converging lens forms a real inverted image on a sensor. Changing object distance changes the required lens-to-sensor distance. Aperture controls light admitted and affects depth of field; it does not change focal length in this model.','For a 50 mm lens and an object 1000 mm away, v ≈ 52.6 mm. Moving the sensor to this position gives focus. The sensor blur is a qualitative cue, not a photographic optical calculation.']
 ]},
 {id:'thermal',name:'Thermal physics',intro:'Follow energy through materials, melt ice, determine specific heat capacity and mix warm and cool water.',categories:['Temperature and energy','Conduction convection radiation','Specific heat capacity','Latent heat and phases','Thermal equilibrium','Energy problems'],lessons:[
 ['Temperature and internal energy','Temperature describes thermal state and relates to average particle kinetic energy. Internal energy includes microscopic kinetic and potential energy. Heat is energy transferred because of a temperature difference.','A large warm bath may contain more internal energy than a tiny hotter cup, even though the cup has a higher temperature.'],
 ['Three transfer mechanisms','Conduction transfers energy through interactions and mobile electrons in metals. Convection is bulk fluid motion caused by density differences in a gravitational field. Thermal radiation is electromagnetic and can pass through a vacuum.','Touch a metal spoon, watch heated water circulate, and compare matt black and shiny surfaces. Visible particle/ray speeds in the model are illustrative.'],
 ['Specific heat capacity','E = mcΔT, with E in J, mass in kg and c in J/(kg·°C) or J/(kg·K). A temperature difference has the same numerical value in kelvin and °C. Ideal calculations neglect losses and container heat capacity.','Heating 0.50 kg of water by 10°C takes 0.50 × 4200 × 10 = 21,000 J.'],
 ['Changes of state','During a change of state at fixed pressure, supplied energy changes phase rather than temperature. E = mL. Our ice/water curve uses 0°C melting, cᵢ = 2100, c𝑤 = 4200 J/(kg·°C) and Lf = 334,000 J/kg; heating ends below boiling.','Melting 0.20 kg of ice at 0°C needs 66,800 J. First warming ice from −20°C requires additional energy.'],
 ['Thermal equilibrium','In an isolated mixture, energy lost by the warmer sample equals energy gained by the cooler sample. Equal final temperature does not mean equal internal energies. No phase change is modelled in the mixing investigation.','Mix 0.20 kg of water at 80°C with 0.30 kg at 20°C: Tf = (0.2×80 + 0.3×20)/0.5 = 44°C.']
 ]},
 {id:'kinematics',name:'Motion and projectiles',intro:'Drive a trolley, read motion graphs, drop objects in a vacuum and resolve a projectile’s motion.',categories:['Motion quantities','Motion graphs','Free fall','Projectiles','Stopping distance','Catch-up and delayed starts'],lessons:[
 ['Distance, displacement and motion','Distance is path length; displacement is change in position with direction. Speed is scalar; velocity has direction. Acceleration is the rate of change of velocity. The trolley’s direction can change while position remains positive.','Move 10 m east then 4 m west: distance = 14 m, displacement = 6 m east.'],
 ['Graphs and constant acceleration','The gradient of a position–time graph is velocity; the gradient of velocity–time is acceleration. Signed area under velocity–time gives displacement. For constant a: v = u + at and s = ut + ½at².','At u = 4 m/s, a = −2 m/s² and t = 4 s, displacement is 0 m, although total distance is 8 m.'],
 ['Free fall','Without air resistance, all objects at the same location share acceleration g ≈ 9.81 m/s², regardless of mass. The vacuum model releases objects from rest.','From 20 m, t = √(2h/g) ≈ 2.02 s and impact speed ≈ 19.8 m/s. Feather and ball land together in a vacuum.'],
 ['Projectile components','In the ideal model, horizontal velocity remains constant while vertical acceleration is −g. Resolve u into u cosθ and u sinθ. At the highest point, vertical velocity is zero but horizontal velocity usually is not.','At 20 m/s and 45° from level ground, flight time ≈ 2.88 s and range ≈ 40.8 m. Complementary angles give equal range only for equal launch/landing heights without drag.'],
 ['Reaction and braking','Thinking distance = speed × reaction time. With constant braking deceleration, braking distance = v²/(2a). Total stopping distance adds both. This idealised model does not simulate tyre or road mechanics.','At 20 m/s, 0.7 s reaction time and 5 m/s² braking deceleration, thinking distance is 14 m and braking distance 40 m: 54 m total.']
 ]},
 {id:'dynamics',name:'Forces and dynamics',intro:'Pull a trolley, test friction, release a block on a slope and connect two masses with a light string.',categories:['Newton’s laws','Resultant force and acceleration','Weight and normal force','Friction','Inclined planes','Connected bodies'],lessons:[
 ['Newton’s laws','A zero resultant force means constant velocity, including rest. For constant mass, resultant F = ma. Interaction forces are equal and opposite but act on different bodies, so they do not cancel on one body’s free-body diagram.','A 2 kg trolley pulled by 6 N on a frictionless track accelerates at 3 m/s². Its weight and normal force balance vertically.'],
 ['Mass, weight and diagrams','Mass is measured in kg; weight W = mg in N. The normal force is perpendicular to the contact surface. It need not equal weight: on an unaccelerated slope without other perpendicular forces, N = mg cosθ.','A 5 kg mass has weight 49.05 N on Earth. Draw only forces acting on the chosen body. Arrow lengths share a scale within each diagram.'],
 ['Static and sliding friction','Static friction adjusts up to μsN. Sliding friction is modelled as μkN opposite relative sliding. For simplicity these investigations use one selected coefficient as both μs and μk. If the available driving force is below the static limit, the block stays at rest.','A 2 kg block with μ = 0.30 can remain at rest against a 4 N pull because μN ≈ 5.89 N; friction is then 4 N, not 5.89 N.'],
 ['Inclined planes','Resolve weight into mg sinθ down the slope and mg cosθ into the surface. For downhill sliding, a = g(sinθ − μ cosθ); use the static limit before deciding that it slides.','At 30° with μ = 0.20, a ≈ 3.21 m/s² down the slope. Mass cancels from this ideal expression.'],
 ['Connected bodies','A light, inextensible string over a frictionless massless pulley gives equal acceleration magnitudes and equal tension on both sides. Analyse each body separately and the system together. Tension is usually not equal to the hanging weight during acceleration.','For a 3 kg trolley and 1 kg hanging mass with no friction, a = 9.81/4 ≈ 2.45 m/s² and tension ≈ 7.36 N.']
 ]}
];
export const experiments=[
 {unit:'electricity',id:'circuits',title:'Build and measure a circuit',tag:'Connect · switch · measure',intro:'Place the resistors, close the switch and follow the charge around the circuit.',controls:[select('kind','Circuit arrangement','series',[['single','One resistor'],['series','Series'],['parallel','Parallel']]),range('voltage','Supply voltage',6,2,12,1,'V'),range('r1','Resistance R₁',10,5,40,5,'Ω'),range('r2','Resistance R₂',20,5,40,5,'Ω')],steps:[step('Drag the resistor pack into the circuit gap.',[125,260],[510,270],'resistors'),step('Click the ammeter to connect the measuring leads.'),step('Close the switch on the circuit to start the charge flow.')],duration:6,model(v,t){const m=S.circuit(v.voltage,v.r1,v.r2,v.kind);return {...result([['Supply current',fmt(m.current)+' A'],['Total resistance',fmt(m.resistance)+' Ω'],['Power transferred',fmt(m.power)+' W']],`V = IR · ${v.voltage} V = ${fmt(m.current)} A × ${fmt(m.resistance)} Ω`,`Ideal ohmic resistors, constant temperature, zero-resistance wires. Conventional current is shown; dot speed is a visual cue. R₁: ${fmt(m.i1)} A, ${fmt(m.v1)} V. ${v.kind==='single'?'':`R₂: ${fmt(m.i2)} A, ${fmt(m.v2)} V.`}`,question('What happens to the total resistance when these two resistors are connected in parallel instead of series?','It is smaller than either branch resistance.',['It equals the sum of both resistances.','It doubles the larger resistance.','It becomes zero.'],'Parallel branches provide additional conducting paths; 1/R = 1/R₁ + 1/R₂.'),{x:'Voltage / V',y:'Current / A',points:Array.from({length:13},(_,i)=>[i,i/m.resistance])}),...m};}},
 {unit:'electricity',id:'charges',title:'Move charges and measure the force',tag:'Drag · separate · compare',intro:'Place the second charge on the rail. Drag it to investigate distance and use the sign selector to reverse its direction.',controls:[range('q1','Charge A',2,-5,5,1,'μC'),range('q2','Charge B',3,-5,5,1,'μC'),range('distance','Centre separation',.5,.2,1.2,.05,'m'),select('field','Field extension','off',[['off','Force arrows'],['on','Show field of charge A']])],steps:[step('Place charge B on the right-hand rail.',[125,260],[700,270],'charge'),step('Click the force meter to zero the display.'),step('Click charge A to reveal the force vectors.')],duration:5,model(v){const m=S.coulomb(v.q1,v.q2,v.distance);return {...result([['Force magnitude',fmt(m.force,4)+' N'],['Interaction',m.type],['Separation',fmt(v.distance)+' m']],`F = k|q₁q₂|/r² · k = 8.99 × 10⁹ N m²/C²`,`Point charges in air approximated as vacuum. Equal and opposite force arrows act on different charges. A neutral point charge gives zero force in this ideal model; polarisation is not included.${v.field==='on'?` Field of A at B: ${fmt(Math.abs(m.field))} N/C.`:''}`,question('If separation is doubled while both charges stay unchanged, the force magnitude becomes…','One quarter as large.',['Twice as large.','Four times as large.','Unchanged.'],'Coulomb’s law has an inverse-square dependence: F ∝ 1/r².'),{x:'Separation / m',y:'Force / N',points:Array.from({length:21},(_,i)=>{const d=.2+i*.05;return[d,S.coulomb(v.q1,v.q2,d).force];})}),...m};}},
 {unit:'electricity',id:'protection',title:'Investigate the protection board',tag:'Isolate · connect · diagnose',intro:'Use a virtual, isolated wiring board to compare an overload with an earth-leakage fault.',controls:[select('fault','Test condition','earth',[['normal','Normal load'],['overload','Balanced overload'],['earth','Earth-leakage fault']]),select('protection','Protection device','rcd',[['rcd','30 mA RCD'],['breaker','16 A circuit breaker'],['none','No protection — comparison only']])],steps:[step('Click the isolation switch to verify the virtual board is isolated.'),step('Move the protective-earth lead to the earth terminal.',[125,260],[590,275],'lead'),step('Close the protected supply switch to run the selected test.')],duration:5,model(v){const m=S.electricalSafety(v.fault,v.protection);return {...result([['Device state',m.trip?'TRIPPED':'Closed'],['Supply after test',fmt(m.current)+' A'],['Initial L–N imbalance',v.fault==='earth'?'80 mA':'0 mA']],`RCD: compare I_live and I_neutral · Breaker: compare load current with rating`,`Simplified diagnostic model, not trip-time curves. Prospective current is ${fmt(m.prospective)} A; a ${v.protection==='rcd'?'30 mA imbalance threshold':v.protection==='breaker'?'16 A overcurrent threshold':'comparison without protection'} is used. Never work on live mains; actual socket changes require qualified supervision.`,question('Which fault can trip an RCD even when the total current is below a breaker’s rating?','Current leaking to earth.',['A balanced load of 8 A.','Equal live and neutral currents.','A lamp being switched off.'],'An RCD detects sufficient live–neutral imbalance, while the breaker responds to overcurrent.'),{x:'Test stage',y:'Supply / A',points:[[0,0],[1,0],[1.01,m.prospective],[2,m.prospective],[2.01,m.current],[5,m.current]]}),...m};}},
 {unit:'electricity',id:'energy',title:'Read a household energy meter',tag:'Plug in · switch · budget',intro:'Connect a model appliance, run the accelerated clock and compare its energy use and cost.',controls:[range('power','Appliance power',2000,100,3000,100,'W'),range('hours','Use time',3,.5,8,.5,'h'),range('tariff','Price per kWh',.3,.1,.6,.05,'currency/kWh')],steps:[step('Drag the appliance plug into the meter socket.',[125,260],[640,275],'plug'),step('Click the meter face to reset its reading.'),step('Switch on the appliance at its own power button.')],duration:6,model(v,t){const m=S.energyUse(v.power,v.hours,v.tariff),fraction=S.clamp(t/6,0,1);return {...result([['Energy so far',fmt(m.energy*fraction)+' kWh'],['Cost so far',fmt(m.cost*fraction)+' currency'],['Modelled use time',fmt(v.hours*fraction)+' h']],`E = P × t · ${v.power/1000} kW × ${v.hours} h = ${fmt(m.energy)} kWh`,`Constant power; 230 V supply; tariff excludes standing charges and taxes. Accelerated time is used. The final cost is ${fmt(m.cost)} currency units.`,question('Which change halves this appliance’s electrical energy use at unchanged power?','Using it for half the time.',['Doubling the use time.','Doubling the tariff.','Changing the price without changing time.'],'Energy depends on power and time, E = Pt; tariff affects cost, not energy.'),{x:'Use time / h',y:'Energy / kWh',points:[[0,0],[v.hours,m.energy]]}),...m};}},
 {unit:'waves',id:'wave-maker',title:'Operate the wave machine',tag:'Connect · oscillate · observe',intro:'Move a spring into place and follow the marked particle as energy travels along it.',controls:[select('type','Wave type','transverse',[['transverse','Transverse string'],['longitudinal','Longitudinal spring']]),range('frequency','Frequency',2,1,5,.5,'Hz'),range('wavelength','Wavelength',2,1,4,.5,'m'),range('amplitude','Amplitude',.4,.1,.6,.1,'m')],steps:[step('Fit the string or spring to the driver.',[125,260],[420,270],'spring'),step('Click the marked particle to tag it for observation.'),step('Turn on the oscillator at the driver.')],duration:6,model(v){const m=S.wave(v.frequency,v.wavelength);return {...result([['Wave speed',fmt(m.speed)+' m/s'],['Period',fmt(m.period)+' s'],['Frequency',fmt(v.frequency)+' Hz']],`v = fλ = ${v.frequency} × ${v.wavelength} = ${fmt(m.speed)} m/s`,`An ideal non-dispersive wave. Changing f and λ independently represents selecting a different model speed; it is not a claim that a fixed string can have any speed. A marked particle oscillates but does not travel with the crest.`,question('What moves along the string or spring with the wave?','Energy; each particle oscillates about its equilibrium.',['Every particle travels to the far end.','Only matter, with no energy.','The medium disappears behind the wave.'],'Wave propagation transfers energy without net transport of the medium.'),{x:'Time / s',y:'Tagged particle displacement / m',points:Array.from({length:121},(_,i)=>[i/20,v.amplitude*Math.sin(2*Math.PI*v.frequency*i/20)])}),...m};}},
 {unit:'waves',id:'sound',title:'Measure sound, echoes and a siren',tag:'Place microphone · emit · listen',intro:'Use the microphone trace, reflected pulse and moving siren to connect pitch, amplitude and travel time.',controls:[select('mode','Investigation','echo',[['echo','Echo range finder'],['tone','Tone and microphone'],['doppler','Moving siren']]),range('frequency','Source frequency',600,200,1000,100,'Hz'),range('amplitude','Signal amplitude',.6,.2,1,.2,'relative'),range('distance','Reflector distance',85,34,170,17,'m'),range('sourceSpeed','Siren speed',20,0,60,5,'m/s')],steps:[step('Move the microphone onto the stand.',[125,260],[400,275],'microphone'),step('Click the microphone to arm the recording.'),step('Press the speaker or siren’s own emit button.')],duration:6,model(v){const m=S.sound(v.frequency,340,v.distance,v.sourceSpeed);return {...result(v.mode==='doppler'?[['Approaching frequency',fmt(m.approach)+' Hz'],['Receding frequency',fmt(m.recede)+' Hz'],['Source frequency',v.frequency+' Hz']]:[['Wavelength',fmt(m.wavelength,3)+' m'],['Echo delay',fmt(m.echo)+' s'],['Source frequency',v.frequency+' Hz']],v.mode==='doppler'?'f′ = fv/(v ∓ vₛ)':'v = fλ · reflector distance = v × echo delay / 2',`Sound speed fixed at 340 m/s. The trace and travelling pulses are slowed for visibility; numerical delay is not screen playback time. ${v.mode==='doppler'?'The source moves below sound speed; observers are stationary.':'Larger amplitude changes the trace height; higher frequency changes its spacing.'}`,question('Why is the distance to a reflector half the speed multiplied by the echo delay?','The sound travels to the reflector and back.',['Sound travels at half its usual speed.','An echo has half the original frequency.','The reflector moves towards the source.'],'The measured delay includes both outward and return journeys.'),{x:'Time / ms',y:'Microphone signal / relative',points:Array.from({length:121},(_,i)=>[i/12,v.amplitude*Math.sin(2*Math.PI*v.frequency*i/12000)])}),...m};}},
 {unit:'waves',id:'spectrum',title:'Tune an electromagnetic detector',tag:'Fit detector · tune · transmit',intro:'Select a band on the spectrum strip and watch how the detector and real-life application change.',controls:[select('band','Spectrum band','visible',[['radio','Radio'],['microwave','Microwave'],['infrared','Infrared'],['visible','Visible'],['ultraviolet','Ultraviolet'],['xray','X-ray'],['gamma','Gamma']])],steps:[step('Place the detector opposite the source.',[125,260],[730,275],'detector'),step('Click the detector to calibrate it for the band selected above.'),step('Press the source’s transmit switch.')],duration:6,model(v){const values={radio:[1e6,'Broadcast radio'],microwave:[1e10,'Satellite communication'],infrared:[1e13,'Thermal imaging'],visible:[5e14,'Vision and photography'],ultraviolet:[1e16,'Fluorescence and surface treatment'],xray:[1e18,'Medical imaging with controlled exposure'],gamma:[1e20,'Cancer treatment with controlled exposure']},[f,use]=values[v.band],wavelength=3e8/f;return {...result([['Frequency',f.toExponential(1)+' Hz'],['Vacuum wavelength',wavelength.toExponential(2)+' m'],['Application',use]],'c = fλ = 3.00 × 10⁸ m/s in vacuum',`Representative frequency within each broad band; boundaries vary. Wave drawings are schematic, not a shared spatial scale. Higher frequency corresponds to shorter wavelength. UV, X-ray and gamma require appropriate exposure controls.`,question('Which property is the same for all electromagnetic bands in vacuum?','Their speed.',['Their frequency.','Their wavelength.','Their biological effects.'],'All electromagnetic waves travel at c in vacuum, but frequencies, wavelengths and interactions differ.'),{x:'Band index (not linear frequency)',y:'log₁₀ frequency / Hz',points:Object.values(values).map(([n],i)=>[i+1,Math.log10(n)])}),frequency:f,wavelength,use};}},
 {unit:'waves',id:'ripple-tank',title:'Explore a ripple tank',tag:'Position boundary · pulse · compare',intro:'Place a barrier, shallow region or gap in the tank, then send wavefronts towards it.',controls:[select('mode','Obstacle','gap',[['gap','Narrow gap — diffraction'],['boundary','Shallow water — refraction'],['wall','Wall — reflection']]),range('wavelength','Incoming wavelength',2,1,4,.5,'cm'),range('gap','Gap width',2,1,8,.5,'cm'),range('ratio','Shallow/deep wave speed',.6,.4,.9,.1,'ratio')],steps:[step('Place the boundary insert in the centre of the tank.',[125,260],[550,265],'barrier'),step('Click the wave driver to set its initial level.'),step('Start the paddle at the left edge of the water.')],duration:6,model(v){const spread=v.wavelength/v.gap;return result([['Gap / wavelength',fmt(v.gap/v.wavelength)],['Shallow wavelength',fmt(v.wavelength*v.ratio)+' cm'],['Frequency at boundary','Unchanged']],v.mode==='boundary'?'v₂/v₁ = λ₂/λ₁ at unchanged f':v.mode==='gap'?'More spreading when gap width ≈ wavelength':'Angle of incidence = angle of reflection',`Top-down schematic. Diffraction wavefronts illustrate relative spreading, not a numerical intensity solution. Incoming and reflected waves are drawn separately for clarity.`,question('When water waves enter a region where they travel more slowly, what remains unchanged?','Frequency.',['Wave speed.','Wavelength.','All three must increase.'],'The source sets the frequency; slower speed at the same frequency means a shorter wavelength.'),{x:'Gap / wavelength',y:'Relative spreading cue',points:[.25,.5,1,2,3,4,6,8].map(x=>[x,Math.min(1,1/x)])});}},
 {unit:'optics',id:'mirror',title:'Trace a reflected ray',tag:'Place mirror · aim · illuminate',intro:'Move the mirror onto its mount and test where the reflected ray goes. Add a card to block its path.',controls:[range('angle','Angle from the normal',35,10,70,5,'°'),select('card','Card position','clear',[['clear','Clear reflected path'],['blocked','Card across reflected path']])],steps:[step('Move the plane mirror into its mount.',[125,260],[550,275],'mirror'),step('Click the protractor to mark the normal.'),step('Switch on the ray-box beam.')],duration:6,model(v){return result([['Incidence angle',v.angle+'°'],['Reflection angle',v.angle+'°'],['Ray reaches detector',v.card==='blocked'?'No — card blocks this path':'Yes']],'i = r · angles measured from the normal','The ray diagram follows one selected path. The card blocks light only where it intersects a path; other unobstructed paths can still form a visible image. A plane mirror image is virtual, upright and equally far behind the surface.',question('Why can a mirror still show an object partly hidden by a card?','Some object–mirror–eye rays may pass around the card.',['The mirror remembers the object.','The card creates light behind itself.','Light crosses every opaque card.'],'Visibility depends on an unobstructed complete ray path, not on whether a card is somewhere near the object.'),{x:'Incidence / °',y:'Reflection / °',points:[[0,0],[80,80]]});}},
 {unit:'optics',id:'refraction',title:'Aim a laser across a boundary',tag:'Place block · measure · trace',intro:'Move the optical block into position and change the incidence angle to discover refraction and total internal reflection.',controls:[range('angle','Incidence angle',30,0,80,5,'°'),select('medium','Direction','air-glass',[['air-glass','Air → glass'],['glass-air','Glass → air'],['air-water','Air → water']])],steps:[step('Drag the optical block onto the ray table.',[125,260],[580,275],'block'),step('Click the protractor to zero it on the normal.'),step('Switch on the laser head.')],duration:6,model(v){const [n1,n2]=v.medium==='glass-air'?[1.5,1]:v.medium==='air-water'?[1,1.33]:[1,1.5],m=S.refraction(n1,n2,v.angle);return {...result([['Refracted angle',m.tir?'TIR — no transmitted ray':fmt(m.angle)+'°'],['Critical angle',m.critical===null?'Not applicable':fmt(m.critical)+'°'],['Indices n₁ → n₂',n1+' → '+n2]],'n₁ sin i = n₂ sin r',`Ideal boundary; frequency is unchanged. A reflected ray can coexist with refraction; intensity splitting is not modelled. TIR occurs only from higher to lower refractive index above the critical angle.`,question('What is required for total internal reflection?','Higher to lower refractive index, above the critical angle.',['Lower to higher index at any angle.','Incidence of exactly 0°.','Any light entering glass.'],'Both conditions must hold. At the critical angle the transmitted ray runs along the boundary.'),{x:'Incidence / °',y:'Refraction / °',points:Array.from({length:81},(_,a)=>[a,S.refraction(n1,n2,a).angle]).filter(p=>p[1]!==null)}),...m,n1,n2};}},
 {unit:'optics',id:'lenses',title:'Move a lens on the optical bench',tag:'Mount · position · focus',intro:'Place a converging or diverging lens and move the object along its rail. Compare the image with the construction rays.',controls:[select('type','Lens','converging',[['converging','Converging'],['diverging','Diverging']]),range('focal','Focal-length magnitude',10,5,15,1,'cm'),range('object','Object distance',30,5,60,1,'cm')],steps:[step('Drag the lens onto the central holder.',[125,260],[550,260],'lens'),step('Click the object arrow to set its height.'),step('Turn on the object lamp to trace the rays.')],duration:6,model(v){const f=v.type==='converging'?v.focal:-v.focal,m=S.lens(f,v.object);return {...result([['Image distance v',m.v===null?'At infinity':fmt(m.v)+' cm'],['Magnification m',m.m===null?'Undefined':fmt(m.m)],['Image type',m.kind]],'1/f = 1/u + 1/v · m = −v/u','Thin-lens paraxial construction. Solid rays are real light paths; dashed extensions locate virtual images. The bench can clip images far outside its range; numerical readings remain valid. Drag the object arrow directly or use its distance slider.',question('A diverging lens with a real object forms what kind of image in this model?','Virtual, upright and smaller.',['Always real and inverted.','Always the same size and real.','Always at infinity.'],'For f < 0 and u > 0, v < 0 and 0 < m < 1.'),{x:'Object distance / cm',y:'Image distance / cm',points:Array.from({length:56},(_,i)=>{const u=i+5;return[u,S.lens(f,u).v];}).filter(p=>p[1]!==null&&Math.abs(p[1])<=100)}),...m,f};}},
 {unit:'optics',id:'camera',title:'Focus a camera on its sensor',tag:'Fit lens · focus · expose',intro:'Fit the camera lens, slide the sensor to the focus point and take a virtual photograph.',controls:[range('object','Object distance',1000,500,5000,250,'mm'),range('focal','Lens focal length',50,35,70,5,'mm'),range('sensor','Lens-to-sensor distance',52,35,85,.5,'mm'),select('aperture','Aperture','4',[['2','f/2 — more light'],['4','f/4'],['8','f/8 — less light']])],steps:[step('Move the camera lens into its mount.',[125,260],[500,270],'lens'),step('Slide the sensor to focus. Click the sensor when its focus indicator is green.'),step('Press the camera’s shutter to expose the image.')],duration:5,model(v){const m=S.lens(v.focal,v.object),error=Math.abs(v.sensor-m.v),focused=error<=.6;return {...result([['Required sensor distance',fmt(m.v)+' mm'],['Your sensor position',fmt(v.sensor)+' mm'],['Focus',focused?'Focused':'Move the sensor to focus']],`1/v = 1/${v.focal} − 1/${v.object} mm⁻¹`,`Thin-lens camera. Focus tolerance is ±0.6 mm for this activity; blur is a qualitative illustration. Aperture brightness scales with 1/(f-number)²; aperture does not alter the model’s focal length.`,question('When a nearby object moves farther away, the required sensor distance approaches…','The focal length.',['Zero in all cases.','Twice the object distance.','A negative distance for every real photograph.'],'As 1/u tends to zero, 1/v tends to 1/f; distant objects form a real image near the focal plane.'),{x:'Object distance / mm',y:'Sensor distance / mm',points:Array.from({length:19},(_,i)=>{const u=500+i*250;return[u,S.lens(v.focal,u).v];})}),...m,error,focused};}},
 {unit:'thermal',id:'heat-transfer',title:'Follow the paths of thermal energy',tag:'Position · heat · observe',intro:'Use a metal bar, convection cell or radiation detector to identify how energy moves.',controls:[select('mode','Apparatus','conduction',[['conduction','Conduction bar'],['convection','Convection cell'],['radiation','Radiation detector']]),select('material','Bar material','copper',[['copper','Copper'],['steel','Steel'],['wood','Wood']]),select('surface','Radiation surface','black',[['black','Matt black'],['shiny','Shiny silver']])],steps:[step('Place the apparatus on the heat-source stand.',[125,260],[540,270],'thermal'),step('Click the thermometer to begin measuring.'),step('Turn on the heater at its own switch.')],duration:7,model(v,t){const rate={copper:1,steel:.35,wood:.05}[v.material],p=S.clamp(t/7,0,1),rise=v.mode==='conduction'?60*(1-Math.exp(-3*rate*p)):v.mode==='convection'?35*p:(v.surface==='black'?40:8)*p;return {...result([['Detector temperature',fmt(20+rise)+'°C'],['Mechanism',v.mode],['Time scale','Illustrative accelerated time']],v.mode==='radiation'?'Thermal radiation transfers energy without a medium':v.mode==='convection'?'Warm fluid rises; cooler fluid returns':'Energy flows from hot to cold along the bar','Qualitative transfer model, not a measured conductivity or heat-transfer coefficient. Equal geometries and initial temperature are assumed. Black surfaces absorb more thermal radiation than shiny surfaces under this comparison.',question('Which mechanism transfers energy through the vacuum between the Sun and Earth?','Radiation.',['Convection of air.','Conduction through empty space.','Mass flow of warm metal.'],'Electromagnetic radiation needs no material medium.'),{x:'Model time / s',y:'Detector temperature / °C',points:Array.from({length:21},(_,i)=>[i*7/20,20+(v.mode==='conduction'?60*(1-Math.exp(-3*rate*i/20)):v.mode==='convection'?35*i/20:(v.surface==='black'?40:8)*i/20)])}),rise};}},
 {unit:'thermal',id:'heating-curve',title:'Warm and melt an ice sample',tag:'Load ice · place probe · heat',intro:'Heat ice from −20°C and watch the temperature plateau while the solid melts.',controls:[range('mass','Ice mass',.2,.1,.5,.1,'kg'),range('power','Heater power',500,200,1000,100,'W')],steps:[step('Move the ice sample into the insulated beaker.',[125,260],[540,270],'ice'),step('Click the probe to lower it into the sample.'),step('Turn on the immersion heater.')],duration:8,model(v,t){const duration=v.mass*(2100*20+334000+4200*40)/v.power,elapsed=duration*S.clamp(t/8,0,1),m=S.heating(v.mass,v.power,elapsed);return {...result([['Temperature',fmt(m.temperature)+'°C'],['State',m.phase],['Energy supplied',fmt(m.energy/1000)+' kJ']],`E = mcΔT for warming · E = mLf for melting · Lf = 334 kJ/kg`,`Insulated ice/water at atmospheric pressure, no evaporation; the virtual run ends at 40°C. Numerical experiment time ${fmt(elapsed)} s is accelerated into eight screen seconds. During melting, energy changes the phase while temperature stays at 0°C.`,question('Why does the temperature stop rising while the ice melts?','Energy changes the phase rather than raising temperature.',['The heater transfers no energy.','The mass disappears.','The thermometer must be broken.'],'At the melting point, latent energy increases the potential part of internal energy during the change of state.'),{x:'Energy / kJ',y:'Temperature / °C',points:Array.from({length:101},(_,i)=>{const n=S.heating(v.mass,v.power,duration*i/100);return[n.energy/1000,n.temperature];})}),...m,duration,elapsed};}},
 {unit:'thermal',id:'heat-capacity',title:'Measure a material’s heat capacity',tag:'Fit block · insert probes · energise',intro:'Put the heater and thermometer into a block, supply a known energy and calculate its specific heat capacity.',controls:[select('material','Material','aluminium',[['aluminium','Aluminium — c = 900'],['copper','Copper — c = 385'],['water','Water — c = 4200']]),range('mass','Mass',.5,.2,1,.1,'kg'),range('energy','Energy supplied',5000,1000,10000,1000,'J')],steps:[step('Move the sample onto its insulating mat.',[125,260],[540,270],'sample'),step('Click the probe holder to insert the heater and thermometer.'),step('Switch on the joulemeter supply.')],duration:6,model(v,t){const c={aluminium:900,copper:385,water:4200}[v.material],delta=v.energy/(v.mass*c),p=S.clamp(t/6,0,1);return {...result([['Temperature',fmt(20+delta*p)+'°C'],['Energy delivered',fmt(v.energy*p)+' J'],['Specific heat capacity',c+' J/(kg·°C)']],`c = E/(mΔT) = ${v.energy}/(${v.mass} × ${fmt(delta)})`,`Initial temperature 20°C; ideal insulation and negligible apparatus heat capacity. Water stays liquid in the offered range. Real experiments need loss corrections and good thermal contact.`,question('For equal mass and supplied energy, a larger specific heat capacity gives…','A smaller temperature rise.',['A larger temperature rise.','The same rise in all materials.','No change in internal energy.'],'ΔT = E/(mc), so a larger c gives a smaller ΔT.'),{x:'Energy / J',y:'Temperature / °C',points:[[0,20],[v.energy,20+delta]]}),c,delta};}},
 {unit:'thermal',id:'equilibrium',title:'Mix warm and cool water',tag:'Pour · stir · balance energy',intro:'Pour warm water into cool water, stir the mixture and check the shared equilibrium temperature.',controls:[range('hotMass','Warm-water mass',.2,.1,.5,.1,'kg'),range('coldMass','Cool-water mass',.3,.1,.5,.1,'kg'),range('hot','Warm temperature',80,50,90,5,'°C'),range('cold','Cool temperature',20,10,40,5,'°C')],steps:[step('Pour the warm sample into the insulated mixing cup.',[125,260],[540,270],'jug'),step('Click the stirrer to mix the two samples.'),step('Lower the thermometer to follow the temperatures.')],duration:7,model(v,t){const m=S.equilibrium(v.hotMass,v.hot,v.coldMass,v.cold),p=S.clamp(t/7,0,1);return {...result([['Warm part',fmt(v.hot+(m.temperature-v.hot)*p)+'°C'],['Cool part',fmt(v.cold+(m.temperature-v.cold)*p)+'°C'],['Final equilibrium',fmt(m.temperature)+'°C']],`m₁c(T₁ − Tf) = m₂c(Tf − T₂)`,`Water only, no heat loss, no phase change; container heat capacity neglected. Intermediate temperatures illustrate approach to equilibrium, not an empirical mixing-rate model. Energy transferred from warmer to cooler water: ${fmt(m.transfer/1000)} kJ.`,question('At thermal equilibrium in this isolated mixture, what is true?','Both portions have the same temperature.',['Both portions must have the same mass.','All internal energy has disappeared.','The final temperature is always the arithmetic mean.'],'Energy is shared until temperatures are equal; the arithmetic mean applies only for equal masses of the same material.'),{x:'Approach to equilibrium / relative',y:'Temperature / °C',points:[[0,v.hot],[1,m.temperature]],second:[[0,v.cold],[1,m.temperature]]}),...m};}},
 {unit:'kinematics',id:'motion',title:'Drive a trolley and read its graphs',tag:'Place · zero · release',intro:'Release a trolley with an initial velocity and constant acceleration, then connect its motion to both graphs.',controls:[range('initial','Initial velocity',4,-6,8,1,'m/s'),range('acceleration','Constant acceleration',1,-3,3,.5,'m/s²'),range('time','Motion duration',4,2,6,1,'s'),select('graph','Graph','position',[['position','Position–time'],['velocity','Velocity–time']])],steps:[step('Place the trolley on the motion track.',[125,260],[320,275],'trolley'),step('Click the position sensor to set x = 0.'),step('Press the release catch on the track.')],duration:7,model(v,t){const elapsed=v.time*S.clamp(t/7,0,1),m=S.motion(v.initial,v.acceleration,elapsed);return {...result([['Position x',fmt(m.x)+' m'],['Velocity v',fmt(m.v)+' m/s'],['Elapsed experiment time',fmt(elapsed)+' s']],`v = u + at · x = ut + ½at²`,`One-dimensional constant acceleration; right is positive. The track rescales to fit the complete run. With negative acceleration a trolley may reverse, so distance can exceed displacement.`,question('What does the gradient of a velocity–time graph represent?','Acceleration.',['Position.','Distance travelled.','Mass.'],'The gradient is change in velocity divided by change in time.'),{x:'Time / s',y:v.graph==='position'?'Position / m':'Velocity / m/s',points:Array.from({length:61},(_,i)=>{const time=v.time*i/60,n=S.motion(v.initial,v.acceleration,time);return[time,v.graph==='position'?n.x:n.v];})}),...m,elapsed};}},
 {unit:'kinematics',id:'free-fall',title:'Drop a feather and a ball in a vacuum',tag:'Load · evacuate · release',intro:'Place both objects in the chamber, remove the air and release them together.',controls:[range('height','Drop height',20,5,50,5,'m'),range('mass','Ball mass',1,.5,5,.5,'kg'),select('gravity','Location','earth',[['earth','Earth — g = 9.81 m/s²'],['moon','Moon — g = 1.62 m/s²']])],steps:[step('Place the feather and ball into the release cradle.',[125,260],[490,130],'falling'),step('Click the pump to evacuate the chamber.'),step('Open the release catch at the top of the chamber.')],duration:6,model(v,t){const g=v.gravity==='earth'?9.81:1.62,duration=Math.sqrt(2*v.height/g),elapsed=duration*S.clamp(t/6,0,1),m=S.fall(v.height,g,elapsed);return {...result([['Height above floor',fmt(m.y)+' m'],['Downward speed',fmt(m.v)+' m/s'],['Fall time',fmt(m.duration)+' s']],`h = ½gt² · v = gt`,`Both objects start from rest in a vacuum. Their masses do not enter the ideal acceleration. Changing location changes g. In air, drag depends on shape, area and motion, so a feather and ball need not fall together.`,question('Why do the feather and ball land together in this vacuum model?','Both have the same gravitational acceleration.',['Both have equal mass.','The feather has no weight.','Gravity is absent in a vacuum.'],'Without air resistance, acceleration g is independent of mass at a given location.'),{x:'Time / s',y:'Height / m',points:Array.from({length:61},(_,i)=>{const time=duration*i/60;return[time,S.fall(v.height,g,time).y];})}),...m,g,elapsed};}},
 {unit:'kinematics',id:'projectile',title:'Aim and launch a projectile',tag:'Load · aim · launch',intro:'Load the launcher, aim it using the handle and watch horizontal and vertical components separately.',controls:[range('speed','Launch speed',20,10,30,1,'m/s'),range('angle','Launch angle',45,15,75,1,'°'),range('height','Launch height',0,0,10,1,'m')],steps:[step('Load the ball into the launcher.',[125,260],[290,310],'ball'),step('Click the aiming handle to lock your selected angle.'),step('Press the launcher trigger beside the barrel.')],duration:7,model(v,t){const whole=S.projectile(v.speed,v.angle,v.height),m=S.projectile(v.speed,v.angle,v.height,9.81,whole.duration*S.clamp(t/7,0,1));return {...result([['Horizontal velocity',fmt(m.vx)+' m/s'],['Vertical velocity',fmt(m.vyNow)+' m/s'],['Predicted range',fmt(m.range)+' m']],`uₓ = u cosθ · uᵧ = u sinθ · aᵧ = −9.81 m/s²`,`No air resistance; flat landing surface; height measured above the landing level. Horizontal speed stays constant. The graph shows the spatial trajectory, not height against time. Vectors share a common visual scale.`,question('At the highest point, which velocity component is zero?','The vertical component only.',['The horizontal component only.','Both components.','Neither can ever be zero.'],'Gravity changes vertical velocity; horizontal velocity remains constant without drag.'),{x:'Horizontal distance / m',y:'Height / m',points:Array.from({length:81},(_,i)=>{const n=S.projectile(v.speed,v.angle,v.height,9.81,whole.duration*i/80);return[n.x,n.y];})}),...m};}},
 {unit:'kinematics',id:'stopping',title:'Test reaction and braking distance',tag:'Place marker · arm · stop',intro:'Set speed and reaction time, then watch the driver react before the brakes slow the car.',controls:[range('speed','Initial speed',20,10,30,1,'m/s'),range('reaction','Reaction time',.7,.3,1.5,.1,'s'),range('deceleration','Braking deceleration',5,2,8,.5,'m/s²')],steps:[step('Place the hazard marker on the test road.',[125,260],[760,280],'cone'),step('Click the dashboard to arm the motion logger.'),step('Press the hazard signal beside the road to start the test.')],duration:7,model(v,t){const m=S.stopping(v.speed,v.reaction,v.deceleration),elapsed=m.time*S.clamp(t/7,0,1),brake=Math.max(0,elapsed-v.reaction),speed=Math.max(0,v.speed-v.deceleration*brake),x=elapsed<v.reaction?v.speed*elapsed:m.thinking+v.speed*brake-.5*v.deceleration*brake*brake;return {...result([['Thinking distance',fmt(m.thinking)+' m'],['Braking distance',fmt(m.braking)+' m'],['Total stopping distance',fmt(m.total)+' m']],`d_stop = vt_reaction + v²/(2a)`,`Constant initial speed during reaction and constant braking deceleration afterwards. This ideal model omits road gradients, vehicle length and changing grip. Amber road marks show thinking distance; coral shows braking.`,question('At fixed deceleration, doubling speed changes braking distance by what factor?','Four.',['Two.','One half.','One.'],'Braking distance is proportional to speed squared, v²/(2a).'),{x:'Time / s',y:'Velocity / m/s',points:[[0,v.speed],[v.reaction,v.speed],[m.time,0]]}),...m,elapsed,speed,x};}},
 {unit:'dynamics',id:'newton',title:'Pull a trolley with a force meter',tag:'Attach · zero · pull',intro:'Attach a force meter to the trolley and compare resultant force, mass and acceleration.',controls:[range('mass','Trolley mass',2,1,5,.5,'kg'),range('force','Horizontal pull',6,0,12,1,'N')],steps:[step('Attach the force meter to the trolley hook.',[125,260],[490,270],'force-meter'),step('Click the meter dial to zero it.'),step('Pull the meter’s handle to apply the selected force.')],duration:6,model(v,t){const a=v.force/v.mass;return {...result([['Resultant horizontal force',v.force+' N'],['Acceleration',fmt(a)+' m/s²'],['Weight',fmt(v.mass*9.81)+' N']],`F_resultant = ma · ${v.force} N = ${v.mass} kg × ${fmt(a)} m/s²`,`Frictionless horizontal track; initial rest. Weight and normal balance vertically. The moving track is scaled for visibility. Force arrows act on the trolley only; the meter’s reaction partner acts on another body.`,question('With the same nonzero resultant force, doubling mass makes acceleration…','Half as large.',['Twice as large.','Four times as large.','Unchanged.'],'a = F/m for a constant mass body.'),{x:'Mass / kg',y:'Acceleration / m/s²',points:Array.from({length:9},(_,i)=>[1+i*.5,v.force/(1+i*.5)])}),a};}},
 {unit:'dynamics',id:'friction',title:'Find the threshold of sliding',tag:'Load · choose surface · pull',intro:'Pull a block across a surface and find when friction can no longer keep it at rest.',controls:[range('mass','Block mass',2,1,5,.5,'kg'),range('force','Applied force',4,0,20,1,'N'),range('mu','Friction coefficient',.3,0,.8,.05,'')],steps:[step('Place the block on the rough track.',[125,260],[470,270],'sample'),step('Click the surface pad to fix the selected roughness.'),step('Pull the force-meter handle attached to the block.')],duration:6,model(v){const m=S.horizontal(v.mass,v.force,v.mu);return {...result([['Friction magnitude',fmt(Math.abs(m.friction))+' N'],['Resultant force',fmt(m.net)+' N'],['Acceleration',fmt(m.a)+' m/s²']],`|F_static| ≤ μN · F_sliding = μN · F_net = F_pull − F_friction`,`Initial rest. One coefficient is used for both static and sliding friction; μN is the limit, not always the actual static friction. ${m.moving?'The applied force exceeds the static limit.':'Static friction balances the applied force, so the block stays at rest.'}`,question('When a 4 N pull is below the static-friction limit, what is the static-friction force magnitude?','4 N.',['Always the full μN limit.','Zero because the block is still.','8 N.'],'Static friction adjusts to balance the applied force until its maximum is reached.'),{x:'Pull / N',y:'Acceleration / m/s²',points:Array.from({length:41},(_,i)=>[i/2,S.horizontal(v.mass,i/2,v.mu).a])}),...m};}},
 {unit:'dynamics',id:'incline',title:'Release a block on an incline',tag:'Set ramp · place block · release',intro:'Change the ramp angle and surface, then use a free-body diagram to predict whether the block slides.',controls:[range('angle','Ramp angle',30,5,50,1,'°'),range('mass','Block mass',2,1,5,.5,'kg'),range('mu','Friction coefficient',.2,0,.8,.05,'')],steps:[step('Place the block at the top of the inclined plane.',[125,260],[410,200],'sample'),step('Click the ramp hinge to lock its selected angle.'),step('Open the catch beside the block to release it.')],duration:6,model(v){const m=S.incline(v.mass,v.angle,v.mu);return {...result([['Down-slope weight component',fmt(m.parallel)+' N'],['Normal force',fmt(m.normal)+' N'],['Down-slope acceleration',fmt(m.a)+' m/s²']],`W∥ = mg sinθ · N = mg cosθ · a = (W∥ − friction)/m`,`Initial rest; straight ramp; one coefficient for static and kinetic friction. Static friction balances the down-slope weight component when it is below μN. The plotted acceleration is zero until slipping begins.`,question('Which expression is the normal force for this block with no other perpendicular forces?','mg cosθ.',['mg sinθ.','Always mg.','ma down the slope.'],'Resolve weight perpendicular to the slope; no acceleration occurs into or away from the ramp.'),{x:'Ramp angle / °',y:'Down-slope acceleration / m/s²',points:Array.from({length:51},(_,angle)=>[angle,S.incline(v.mass,angle,v.mu).a])}),...m};}},
 {unit:'dynamics',id:'connected',title:'Connect a trolley and hanging mass',tag:'Thread · attach · release',intro:'Thread a light string over the pulley and compare both bodies’ acceleration and the string tension.',controls:[range('m1','Trolley mass',3,1,5,.5,'kg'),range('m2','Hanging mass',1,.5,3,.5,'kg'),range('mu','Track friction coefficient',0,0,.5,.05,'')],steps:[step('Thread the string over the pulley.',[125,260],[720,240],'string'),step('Click the hanging mass to attach the string.'),step('Release the catch on the trolley.')],duration:6,model(v){const m=S.connected(v.m1,v.m2,v.mu);return {...result([['Shared acceleration',fmt(m.a)+' m/s²'],['String tension',fmt(m.tension)+' N'],['Hanging weight',fmt(v.m2*9.81)+' N']],`a = (m₂g − friction)/(m₁ + m₂) · T = m₂(g − a)`,`Light inextensible string, massless frictionless pulley, initial rest. One coefficient models static and kinetic friction. Below the static threshold neither mass moves. Tension acts on each body; internal tensions cancel for the combined system.`,question('While the hanging mass accelerates downwards, how does tension compare with its weight?','Tension is smaller than its weight.',['Tension always equals its weight.','Tension is larger than its weight.','Tension must be zero.'],'The hanging mass obeys m₂g − T = m₂a; for a > 0, T < m₂g.'),{x:'Hanging mass / kg',y:'Acceleration / m/s²',points:Array.from({length:11},(_,i)=>{const mass=.5+i*.25;return[mass,S.connected(v.m1,mass,v.mu).a];})}),...m};}}
];
export const defaults=d=>Object.fromEntries(d.controls.map(c=>[c.id,c.value]));
experiments.push({unit:'kinematics',id:'catch-up',title:'Catch up: two objects, two starting stories',tag:'Position · delay · catch up',intro:'Give object A a head start in position or time. Release object B later and predict where their position–time lines meet.',controls:[range('xA','A starting position',20,0,60,5,'m'),range('vA','A speed',3,1,10,1,'m/s'),range('xB','B starting position',0,0,60,5,'m'),range('vB','B speed',5,1,10,1,'m/s'),range('delay','B start delay',2,0,10,1,'s')],steps:[step('Place object B on the second lane.',[125,260],[520,285],'trolley'),step('Click the start clock to arm B’s selected delay.'),step('Press the start signal on the track: A starts now; B waits for its own release.')],duration:8,model(v,t){const m=S.catchUp(v.xA,v.vA,v.xB,v.vB,v.delay),horizon=m.time!==null?Math.max(10,m.time*1.15+2):Math.max(20,v.delay+15),elapsed=horizon*S.clamp(t/8,0,1),a=v.xA+v.vA*elapsed,b=v.xB+v.vB*Math.max(0,elapsed-v.delay);return {...result([['Experiment clock',fmt(elapsed)+' s'],['Meeting after B starts',m.coincident?'Together from B’s release':m.time===null?'No future meeting':fmt(m.time)+' s from A’s start'],['Meeting position',m.position===null?'—':fmt(m.position)+' m']],`xA = ${v.xA} + ${v.vA}t · xB = ${v.xB} + ${v.vB} max(0, t − ${v.delay})`,`Constant positive velocities in parallel lanes. B stays stationary before its delayed start. A meeting means equal position at the same time after B’s release; it is not equal distances travelled. ${m.time!==null?`B has moved for ${fmt(m.time-v.delay)} s when they meet.`:m.coincident?'They remain together after B starts.':'The selected starting gap and relative speed give no meeting after B starts.'}`,question('A starts at 20 m at 3 m/s. B starts at 0 m, 2 s later, at 5 m/s. Which equation finds their meeting time measured from A’s start?','20 + 3t = 5(t − 2).',['20 + 3t = 5t.','3t = 5(t + 2).','20 = (3 + 5)t.'],'At the same clock time t, A has moved for t seconds and B for t − 2 seconds. Equal positions give t = 15 s and x = 65 m.'),{x:'Time since A starts / s',y:'Position / m',points:[[0,v.xA],[horizon,v.xA+v.vA*horizon]],second:[[0,v.xB],[v.delay,v.xB],[horizon,v.xB+v.vB*(horizon-v.delay)]],labels:['Object A','Object B']}),...m,horizon,elapsed,a,b};}});
units.find(u=>u.id==='kinematics').lessons.push(['Catch-up problems and delayed starts','Use one shared clock and one coordinate origin. Before its release, the delayed object remains at its starting position; afterwards use x = x₀ + v(t − delay). Meeting requires equal positions at the same time, not equal distances travelled.','A begins at 20 m at 3 m/s. B begins at 0 m after 2 s, at 5 m/s. Solve 20 + 3t = 5(t − 2): t = 15 s, x = 65 m. B has travelled for 13 s. If the gap grows after B starts, there is no future catch.']);
